// Regular function
function add(a, b) {
  return a + b;
}

// Arrow function
const addNumbers = (a, b) => {
  return a + b;
};

// Short form
const multiply = (a, b) => a * b;

console.log(multiply(5, 4)); // 20

const obj = {
  name: "Jeet",

  regular: function () {
    console.log(this.name);
  },

  arrow: () => {
    console.log(this.name);
  }
};

obj.regular(); // "Jeet"
obj.arrow();   // undefined in a typical module/script context

// Regular functions can have their own this.
// Arrow functions use this from the surrounding scope.

const user = {
  name: "Jeet",

  regular() {
    console.log(this.name);
  },

  arrow: () => {
    console.log(this.name);
  }
};

user.regular(); // "Jeet"
user.arrow();   // undefined in a typical module context

const User = (name) => {
  this.name = name;
};

// const user = new User("Jeet");
// TypeError: User is not a constructor

// Use a regular function or class instead:
function Person(name) {
  this.name = name;
}

const person = new Person("Jeet");
console.log(person.name); // Jeet

const user = {
  name: "Jeet"
};

const greet = () => {
  console.log(this.name);
};

greet.call(user);

// call() cannot change the this value
// of an arrow function.

function regularFunction() {
  const arrowFunction = () => {
    console.log(arguments[0]);
  };

  arrowFunction();
}

regularFunction("Jeet"); // Jeet

// Recommended approach with an arrow function:
const sum = (...numbers) => {
  return numbers.reduce((total, number) => total + number, 0);
};

console.log(sum(10, 20, 30)); // 60

const numbers = [1, 2, 3, 4];

const doubled = numbers.map(number => number * 2);

console.log(doubled); // [2, 4, 6, 8]

setTimeout(() => {
  console.log("Executed after 1 second");
}, 1000);

